-- MarketGo | Base de datos MySQL/MariaDB

CREATE DATABASE IF NOT EXISTS marketgo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE marketgo;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS movimiento_stock, detalle_compra, orden_compra, detalle_venta, venta, oferta, carrito_detalle, carrito, producto, empleado, cuenta_usuario, cliente, proveedor, categoria, rol;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE rol (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(30) NOT NULL UNIQUE, descripcion VARCHAR(180)) ENGINE=InnoDB;
CREATE TABLE categoria (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(10) NOT NULL UNIQUE, nombre VARCHAR(80) NOT NULL UNIQUE, descripcion VARCHAR(220), icono VARCHAR(12)) ENGINE=InnoDB;
CREATE TABLE proveedor (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ruc CHAR(11) NOT NULL UNIQUE, razon_social VARCHAR(180) NOT NULL, telefono VARCHAR(30), correo VARCHAR(140), direccion VARCHAR(180), contacto VARCHAR(100), dias_entrega SMALLINT UNSIGNED DEFAULT 0, condicion_pago VARCHAR(50), categoria_principal_id INT UNSIGNED NULL, calificacion VARCHAR(20), estado ENUM('Activo','Inactivo') DEFAULT 'Activo', CONSTRAINT fk_proveedor_categoria FOREIGN KEY (categoria_principal_id) REFERENCES categoria(id) ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE cliente (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, documento VARCHAR(15) NOT NULL UNIQUE, nombres_razon_social VARCHAR(160) NOT NULL, apellidos_nombre_comercial VARCHAR(160), telefono VARCHAR(30), correo VARCHAR(140), direccion VARCHAR(180), distrito VARCHAR(80), tipo ENUM('Persona natural','Empresa') DEFAULT 'Persona natural', condicion_pago VARCHAR(50) DEFAULT 'Contado', limite_credito DECIMAL(12,2) NOT NULL DEFAULT 0, compras_acumuladas DECIMAL(12,2) NOT NULL DEFAULT 0, estado ENUM('Activo','Inactivo') DEFAULT 'Activo', creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE empleado (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, dni CHAR(8) NOT NULL UNIQUE, nombres VARCHAR(100) NOT NULL, apellidos VARCHAR(120) NOT NULL, telefono VARCHAR(30), correo VARCHAR(140) NOT NULL UNIQUE, cargo VARCHAR(100), area VARCHAR(80), fecha_contratacion DATE, estado ENUM('Activo','Inactivo') DEFAULT 'Activo') ENGINE=InnoDB;
CREATE TABLE cuenta_usuario (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, usuario VARCHAR(80) NOT NULL UNIQUE, correo VARCHAR(140) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, rol_id TINYINT UNSIGNED NOT NULL, cliente_id BIGINT UNSIGNED NULL UNIQUE, empleado_id BIGINT UNSIGNED NULL UNIQUE, activo TINYINT(1) NOT NULL DEFAULT 1, ultimo_acceso DATETIME NULL, creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_usuario_rol FOREIGN KEY (rol_id) REFERENCES rol(id), CONSTRAINT fk_usuario_cliente FOREIGN KEY (cliente_id) REFERENCES cliente(id) ON DELETE SET NULL, CONSTRAINT fk_usuario_empleado FOREIGN KEY (empleado_id) REFERENCES empleado(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE producto (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(20) NOT NULL UNIQUE, nombre VARCHAR(180) NOT NULL, descripcion TEXT, marca VARCHAR(100), presentacion VARCHAR(80), categoria_id INT UNSIGNED NOT NULL, proveedor_id BIGINT UNSIGNED NULL, unidad VARCHAR(30) NOT NULL DEFAULT 'Unidad', precio_compra DECIMAL(12,2) NOT NULL DEFAULT 0, precio_venta DECIMAL(12,2) NOT NULL DEFAULT 0, stock DECIMAL(12,3) NOT NULL DEFAULT 0, stock_minimo DECIMAL(12,3) NOT NULL DEFAULT 0, codigo_barras VARCHAR(32) UNIQUE, lote VARCHAR(50), fecha_vencimiento DATE NULL, almacenamiento VARCHAR(80), origen VARCHAR(80) DEFAULT 'Perú', perecible TINYINT(1) DEFAULT 0, estado ENUM('Disponible','Agotado','Inactivo') DEFAULT 'Disponible', creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_producto_nombre(nombre), INDEX idx_producto_categoria(categoria_id), INDEX idx_producto_stock(stock), CONSTRAINT fk_producto_categoria FOREIGN KEY (categoria_id) REFERENCES categoria(id), CONSTRAINT fk_producto_proveedor FOREIGN KEY (proveedor_id) REFERENCES proveedor(id) ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE oferta (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(20) NOT NULL UNIQUE, nombre VARCHAR(120) NOT NULL, producto_id BIGINT UNSIGNED NULL, descuento VARCHAR(20), precio_anterior DECIMAL(12,2), precio_oferta DECIMAL(12,2), icono VARCHAR(12), estado ENUM('Activa','Programada','Finalizada','Inactiva') DEFAULT 'Programada', fecha_inicio DATE NULL, fecha_fin DATE NULL, CONSTRAINT fk_oferta_producto FOREIGN KEY (producto_id) REFERENCES producto(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE carrito (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cliente_id BIGINT UNSIGNED NOT NULL, estado ENUM('Abierto','Convertido','Abandonado') DEFAULT 'Abierto', creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_carrito_cliente FOREIGN KEY (cliente_id) REFERENCES cliente(id)) ENGINE=InnoDB;
CREATE TABLE carrito_detalle (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, carrito_id BIGINT UNSIGNED NOT NULL, producto_id BIGINT UNSIGNED NOT NULL, cantidad DECIMAL(12,3) NOT NULL DEFAULT 1, precio_unitario DECIMAL(12,2) NOT NULL, UNIQUE KEY uq_carrito_producto(carrito_id,producto_id), CONSTRAINT fk_cd_carrito FOREIGN KEY (carrito_id) REFERENCES carrito(id) ON DELETE CASCADE, CONSTRAINT fk_cd_producto FOREIGN KEY (producto_id) REFERENCES producto(id)) ENGINE=InnoDB;
CREATE TABLE venta (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(30) NOT NULL UNIQUE, cliente_id BIGINT UNSIGNED NULL, empleado_id BIGINT UNSIGNED NULL, fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, metodo_pago VARCHAR(40), direccion_entrega VARCHAR(180), subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, impuesto DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL DEFAULT 0, estado ENUM('Pendiente','En preparación','Enviado','Entregado','Cancelado') DEFAULT 'Pendiente', CONSTRAINT fk_venta_cliente FOREIGN KEY (cliente_id) REFERENCES cliente(id) ON DELETE SET NULL, CONSTRAINT fk_venta_empleado FOREIGN KEY (empleado_id) REFERENCES empleado(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE detalle_venta (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, venta_id BIGINT UNSIGNED NOT NULL, producto_id BIGINT UNSIGNED NOT NULL, codigo_producto VARCHAR(20), nombre_producto VARCHAR(180) NOT NULL, cantidad DECIMAL(12,3) NOT NULL, precio_unitario DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, CONSTRAINT fk_dv_venta FOREIGN KEY (venta_id) REFERENCES venta(id) ON DELETE CASCADE, CONSTRAINT fk_dv_producto FOREIGN KEY (producto_id) REFERENCES producto(id)) ENGINE=InnoDB;
CREATE TABLE orden_compra (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(30) NOT NULL UNIQUE, proveedor_id BIGINT UNSIGNED NOT NULL, fecha DATE NOT NULL, condicion_pago VARCHAR(50), subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, impuesto DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL DEFAULT 0, estado ENUM('Pendiente','Recibida','Cancelada') DEFAULT 'Pendiente', creado_por BIGINT UNSIGNED NULL, fecha_recepcion DATE NULL, CONSTRAINT fk_oc_proveedor FOREIGN KEY (proveedor_id) REFERENCES proveedor(id), CONSTRAINT fk_oc_empleado FOREIGN KEY (creado_por) REFERENCES empleado(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE detalle_compra (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, orden_compra_id BIGINT UNSIGNED NOT NULL, producto_id BIGINT UNSIGNED NOT NULL, cantidad DECIMAL(12,3) NOT NULL, precio_unitario DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, CONSTRAINT fk_dc_orden FOREIGN KEY (orden_compra_id) REFERENCES orden_compra(id) ON DELETE CASCADE, CONSTRAINT fk_dc_producto FOREIGN KEY (producto_id) REFERENCES producto(id)) ENGINE=InnoDB;
CREATE TABLE movimiento_stock (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, tipo ENUM('ENTRADA','SALIDA','AJUSTE') NOT NULL, documento VARCHAR(40), producto_id BIGINT UNSIGNED NOT NULL, cantidad DECIMAL(12,3) NOT NULL, usuario_id BIGINT UNSIGNED NULL, detalle VARCHAR(220), CONSTRAINT fk_ms_producto FOREIGN KEY (producto_id) REFERENCES producto(id), CONSTRAINT fk_ms_usuario FOREIGN KEY (usuario_id) REFERENCES cuenta_usuario(id) ON DELETE SET NULL, INDEX idx_mov_fecha(fecha), INDEX idx_mov_tipo(tipo)) ENGINE=InnoDB;















